import registry as REG
import numpy as np
DES = list(UNC["mc"])

def uncertainty(d):
    d.h1("12. Uncertainty analysis and Monte Carlo simulation", bm="sec_unc", pb=True)
    d.p(f"Parametric uncertainty was propagated by Monte Carlo simulation over all {len(UNC['keys'])} ranged registry parameters [@igos2019]. {NMC:,} input vectors were drawn by Latin hypercube sampling from the triangular and uniform distributions of the registry, and sixteen rank correlations were imposed with the Iman–Conover method (Section 13) [@iman1982]. The same {NMC:,} vectors were applied to all six designs compared (common random numbers), so differences between designs are not blurred by sampling noise and probabilities such as P(HTL cheaper than FAME) are computed draw by draw [@heijungs2020]. Convergence was checked by comparing the first half of the sample with the whole: the medians of MFSP move by less than {max(c['p50'] for c in CONV.values())*100:.2f}% and the 95th percentiles by at most {max(c['p95'] for c in CONV.values())*100:.2f}%, and the standard error of a probability near 0.5 is {se_p(0.5):.3f}.")
    d.fig("F26_mc_box")
    rows = [[k, f2(r["mfsp_p5"]), f2(r["mfsp_p50"]), f2(r["mfsp_p95"]), f1(r["gwp_p5"]), f1(r["gwp_p50"]), f1(r["gwp_p95"]), f0(r["npv_p50"] / 1e6)] for k, r in RISK.items()]
    d.table("mc", f"Monte Carlo results ({NMC:,} draws): 5th, 50th and 95th percentiles of MFSP (USD/L deq) and GWP (g CO₂e/MJ), and median NPV at the CME price (USD M).", ["Design", "MFSP P5", "P50", "P95", "GWP P5", "P50", "P95", "NPV P50"], rows,
            widths=[2.0, 0.7, 0.6, 0.6, 0.7, 0.6, 0.6, 0.8], align=["l"] + ["r"] * 7)
    r1 = RISK["S01 HTL base"]
    d.p(f"For the HTL base, the 90% interval of the MFSP is {f2(r1['mfsp_p5'])}–{f2(r1['mfsp_p95'])} USD/L deq around a median of {f2(r1['mfsp_p50'])}, entirely above the CME price. The median GWP ({f1(r1['gwp_p50'])} g/MJ) is higher than the deterministic value ({f1(H['gwp'])}) because several electricity-related ranges are right-skewed: CO₂ delivery spans 5.6–147 kWh/t around a base of 22 [@zheng2016], mixing 24–100 kWh/ha/d around 48 [@davis2016], and pond N₂O 0.003–0.45% of nitrogen around 0.1% [@guieysse2013,plouviez2017]. Plant life is sampled between 15 and 30 years (uniform), which shifts the Monte Carlo MFSP upward relative to the 30-year deterministic base. Under uncertainty the base design is more likely than not to emit more than fossil diesel (P(GWP < 94) = {pct(r1['p_below_diesel'])}). «fig:F27_mc_joint» shows the joint distribution of cost and climate: only the 2050 net-zero design puts most of its draws below both the CME price and the 65% saving line.")
    d.fig("F27_mc_joint")

def correlation(d):
    d.h1("13. Correlation and dependency analysis", bm="sec_corr", pb=True)
    d.p("Inputs are not independent. Fuel, LPG, hydrogen and methanol prices move with crude oil; urea and DAP prices move together and with energy; the farm and conversion capital factors share the same estimating method; and lipid-rich algae are nitrogen-poor [@laurens2012]. Sixteen Spearman rank correlations were specified («tab:corr») and imposed with the Iman–Conover method, which reorders the sampled marginals to reproduce a target correlation while keeping each distribution unchanged [@iman1982]. Because six targets involve the diesel price, the specified matrix was not positive definite; it was repaired by clipping its negative eigenvalues, which weakens the diesel-price pairs. «tab:corr» lists the targets and the rank correlations realised in the sample: all pairs not involving diesel are within {CORRDEV['other']:.2f} of target, the diesel pairs {CORRDEV['dmin']:.2f}–{CORRDEV['dmax']:.2f} below it.")
    Cr = UNC["input_corr_realised"]; K = UNC["keys"]
    rows = [[NAME.get(a, a), NAME.get(b, b), f"{r:+.1f}", f"{Cr[K.index(a), K.index(b)]:+.2f}"] for a, b, r in UNC["corr"]]
    d.table("corr", "Rank correlations between inputs: target and realised in the sample.", ["Parameter 1", "Parameter 2", "Target ρ", "Realised ρ"], rows, widths=[3, 3, 0.8, 0.8], align=["l", "l", "r", "r"])
    d.p("Output sensitivity to each input was measured with Spearman rank correlation coefficients and partial rank correlation coefficients (PRCC), which remove the linear effect of the other inputs on both variables («fig:F30_spearman», «fig:F31_prcc»). Productivity and HTL yield correlate negatively with MFSP and GWP; the discount rate and the location factor positively with MFSP only; and the electricity parameters with GWP only. For NPV the signs reverse. The PRCC ranks agree with the Sobol' indices in Section 15.")
    d.fig("F30_spearman"); d.fig("F31_prcc")
    ph = UNC["p_htl_beats_fame"]
    d.p(f"«fig:F32_dependency» compares the HTL base with dependencies and with independent inputs. The dependencies barely change the distribution of the MFSP and widen that of NPV slightly, because the correlated price pairs act on both revenue and cost. Because the same draws drive both routes, the dependency between designs can be used directly: HTL is cheaper than FAME in {pct(ph['mfsp'])} of draws and has a lower GWP in {pct(ph['gwp'])}.")
    d.fig("F32_dependency")

def risk(d):
    d.h1("14. Risk and stochastic uncertainty analysis", bm="sec_risk", pb=True)
    d.h2("14.1 Risk metrics")
    d.p("The Monte Carlo draws give the probability of reaching the targets that matter to an investor and to a regulator («fig:F28_risk_probabilities»), and the downside of the investment, expressed as the value at risk (VaR₅, the 5th percentile of NPV) and the conditional value at risk (CVaR₅, the mean of the worst 5%) («fig:F29_npv_cdf», «tab:risk»).")
    d.fig("F28_risk_probabilities")
    rows = [[k, pct(r["p_lt_cme"]), pct(r["p_lt_cme_sampled"]), pct(r["p_npv_pos"]), pct(r["p_save50"]), pct(r["p_save65"]), pct(r["p_below_diesel"]), f0(r["var5"] / 1e6), f0(r["cvar5"] / 1e6)] for k, r in RISK.items()]
    d.table("risk", "Risk metrics (probabilities over the Monte Carlo draws; VaR₅ and CVaR₅ of NPV at the sampled CME price in USD M). P(MFSP<CME fixed) compares each draw with the fixed 2026 benchmark of 2.44 USD/L deq; P(MFSP<CME sampled) and P(NPV>0) use the CME price drawn in the same draw.", ["Design", "P(MFSP<CME fixed)", "P(MFSP<CME sampled)", "P(NPV>0)", "P(save ≥50%)", "P(save ≥65%)", "P(GWP<94)", "VaR₅", "CVaR₅"], rows,
            widths=[1.8, 0.75, 0.8, 0.65, 0.7, 0.7, 0.65, 0.55, 0.55], align=["l"] + ["r"] * 8, size=13)
    d.fig("F29_npv_cdf")
    r54 = RISK["S54 HTL NZ 2050"]; r50 = RISK["S50 HTL CES2 2040"]
    d.p(f"Two benchmark definitions are used, because they answer different questions. P(MFSP < CME fixed) asks whether the plant's cost lies below today's CME price of {f2(CME)} USD/L deq; P(MFSP < CME sampled) asks whether it lies below the CME price drawn in the same Monte Carlo world, and coincides with P(NPV > 0), which is evaluated at that sampled price. Among the 2026 designs evaluated, {NHIT2026} of the {len(DES26) * NMC:,} design-draw combinations reach the fixed CME benchmark. In 2040 under CES2 the probabilities are {pct(r50['p_lt_cme'])} (fixed), {pct(r50['p_lt_cme_sampled'])} (sampled) and {pct(r50['p_npv_pos'])} (NPV > 0); in 2050 under the net-zero pathway they are {pct(r54['p_lt_cme'])}, {pct(r54['p_lt_cme_sampled'])} and {pct(r54['p_npv_pos'])}, with a VaR₅ of {f0(r54['var5']/1e6)} M USD. These are probabilities conditional on the modelled pathway, the parameter ranges and the benchmark, not probabilities that commercial competitiveness will occur. The clean-utilities design (S32) reaches the 50% saving in {pct(RISK['S32 HTL clean utilities']['p_save50'],1)} of draws and the 65% saving in {pct(RISK['S32 HTL clean utilities']['p_save65'])}: its climate case is robust even though its cost case is not.")
    d.h2("14.2 Stochastic cash flows")
    sp = {r["key"]: r for r in REG.R if r["group"].startswith("9")}
    d.p(f"Parametric Monte Carlo treats each input as fixed over the plant's life. Three sources of year-to-year variation were added in a separate simulation of {len(ST['S01 HTL base']['npv']):,} cash-flow paths per case. The fuel price follows a mean-reverting (Ornstein–Uhlenbeck) process in its logarithm, the one-factor model of Schwartz [@schwartz1997], with volatility {sp['sig_price']['base']} and reversion speed {sp['kap_price']['base']} per year. Damaging typhoons arrive as a Poisson process at {sp['lam_typh']['base']} per year, each costing {sp['typh_days']['base']:g} production days and {pct(sp['typh_cost']['base'])} of farm capital in repairs [@cinco2016,corporal2017,sunstar2021odette,lozada2013]. Annual productivity varies with a coefficient of variation of {pct(sp['cv_year']['base'])}, as observed between years at the AzCATI testbed [@mcgowen2023].")
    d.fig("F36_stochastic")
    rows = [[k, pct(v["p_loss"]), f0(v["median"] / 1e6), f0(v["var5"] / 1e6), f0(v["cvar5"] / 1e6)] for k, v in ST.items()]
    d.table("stoch", "Stochastic cash-flow simulation: probability of loss and NPV statistics (USD M).", ["Case", "P(NPV<0)", "Median NPV", "VaR₅", "CVaR₅"], rows, widths=[3, 0.9, 1, 0.9, 0.9], align=["l", "r", "r", "r", "r"])
    s1, s2 = ST["S01 HTL base"], ST["S01 no typhoons"]
    d.p(f"For the 2026 base the typhoons cost about {f0((s2['median']-s1['median'])/1e6)} M USD of median NPV, small next to the {f0(-s1['median']/1e6)} M USD gap to break-even. For the 2050 net-zero design sold at the CME price, {ST_TXT}; sold at the diesel price the probability of loss is {pct(ST['S54 sold at diesel parity']['p_loss'])}, and a price floor at the diesel level, as a mandate or contract-for-difference would provide, lowers it only to {pct(ST['S54 diesel parity + floor']['p_loss'])}. Price support therefore matters less than the level of the reference price: the plant is viable if it is paid what CME costs, not what diesel costs. Because this simulation holds all other parameters at their base values, it isolates year-to-year risk; the parametric uncertainty of Section 12 comes on top. Tax is computed with the same loss-vintage rules as the deterministic cash flow (Section 6.3).")

def gsa(d):
    d.h1("15. Global sensitivity analysis", bm="sec_gsa", pb=True)
    d.p(f"Global sensitivity analysis apportions the variance of the outputs to the inputs while all inputs vary together [@saltelli2010]. It was done in two stages. The Morris method of elementary effects screened all {len(UNC['keys'])} parameters with 20 trajectories on a four-level grid per route [@morris1991]; its mean absolute effect μ* ranks importance and its standard deviation σ flags non-linearity or interaction («fig:F33_morris»). The 30 parameters with the highest combined μ* for MFSP and GWP were then analysed with Sobol' variance decomposition [@sobol2001], using the Saltelli sampling scheme with the Saltelli first-order and Jansen total-order estimators and 200 bootstrap resamples for confidence intervals [@saltelli2010]. HTL used N = {SOB['HTL']['n']:,} base samples ({SOB['HTL']['runs']:,} engine runs) and FAME N = {SOB['FAME']['n']:,} ({SOB['FAME']['runs']:,} runs).")
    d.fig("F33_morris")
    d.fig("F34_sobol_htl"); d.fig("F35_sobol_fame")
    rows = []
    for route in ("HTL", "FAME"):
        for j, out in ((0, "MFSP"), (1, "GWP")):
            for k, s1, st in sob_top(route, j, 5): rows.append([route, out, NAME.get(k, k), f"{s1:.3f}", f"{st:.3f}"])
    d.table("sobol", "Leading Sobol' indices (first order S1, total order ST).", ["Route", "Output", "Parameter", "S1", "ST"], rows, widths=[0.7, 0.7, 3.5, 0.7, 0.7], align=["l", "l", "l", "r", "r"])
    h0 = sob_top("HTL", 0); h1 = sob_top("HTL", 1); f0_ = sob_top("FAME", 0)
    d.p(f"The Sobol' analysis samples its inputs independently, as the Saltelli scheme requires; the indices therefore decompose the variance of the model under independent inputs, not the correlated Monte Carlo distribution of Section 12, which would need a dependent-input method. Section 13 shows that the dependencies change the MFSP distribution little. For the HTL MFSP, productivity (S1 = {h0[0][1]:.2f}, ST = {h0[0][2]:.2f}) and HTL yield (S1 = {h0[1][1]:.2f}, ST = {h0[1][2]:.2f}) have first-order indices summing to {pct(h0[0][1]+h0[1][1])}, their additive share of the variance (total-order indices can overlap through interactions, so their sum, {pct(h0[0][2]+h0[1][2])}, is not a share), followed by the discount rate ({h0[2][2]:.2f}) and the location factor ({h0[3][2]:.2f}). For the HTL GWP, HTL yield leads ({h1[0][2]:.2f}), followed by CO₂ delivery energy ({h1[1][2]:.2f}), mixing energy ({h1[2][2]:.2f}) and productivity ({h1[3][2]:.2f}). For FAME the transesterifiable fraction of the lipid dominates both outputs (ST = {f0_[0][2]:.2f} for MFSP). The first-order indices sum to {SOB['HTL']['S1'][:,0].sum():.2f} and {SOB['HTL']['S1'][:,1].sum():.2f} for the HTL outputs, so the model is close to additive and interactions are small; the confidence intervals are narrow for the leading parameters. The research priorities that follow are clear: productivity and HTL yield for cost, and the electricity used in the ponds for climate. Price and wage parameters, which dominate public debate, explain little of the variance.")

def pareto(d):
    d.h1("16. Pareto analysis and multi-objective optimisation", bm="sec_pareto", pb=True)
    d.p("Which designs are worth building depends on how cost, climate and capital are weighed. Rather than fixing weights, the Pareto front of non-dominated designs was found with NSGA-II, an elitist genetic algorithm with non-dominated sorting and crowding distance [@deb2002], implemented for this study and coupled to the full engine. The decision variables are the route, pond area (50–3,000 ha), liners, aqueous-phase treatment, upgrading location, heat source, electricity supply, nutrient source, CO₂ source and glycerol treatment; the objectives are to minimise MFSP, GWP and total capital investment. The optimisation does not constrain CO₂ supply, so designs above about 1,150 ha are unconstrained multi-source designs. Each run used a population of 100 over 80 generations, for the 2026 background and for the 2040 CES2 and 2050 net-zero pathways. Convergence was tracked with the hypervolume of the cost–climate projection («fig:F39_hypervolume»).")
    d.fig("F37_pareto")
    rows = []
    for k, lab in (("2026", "2026"), ("2040_CES2", "2040 CES2"), ("2050_NZ", "2050 NZ")):
        for key, nm in (("mfsp", "lowest MFSP"), ("gwp", "lowest GWP"), ("tci", "lowest TCI")):
            s = fmin(k, key); D_ = s["D"]
            rows.append([lab, nm, s["route"], f0(s["area"]), D_["elec"].replace("_", " "), D_["heat"], D_["aq"], D_["upgrade"], f2(s["mfsp"]), f1(s["gwp"]), f0(s["tci"])])
    d.table("pareto", "Extreme designs on the Pareto fronts (MFSP in USD/L deq, GWP in g CO₂e/MJ, TCI in USD M).", ["Year", "Extreme", "Route", "Area, ha", "Electricity", "Heat", "Aqueous", "Upgrading", "MFSP", "GWP", "TCI"], rows,
            widths=[0.7, 0.9, 0.5, 0.6, 0.8, 0.6, 0.6, 0.7, 0.5, 0.5, 0.5], align=["l"] * 8 + ["r"] * 3, size=13)
    a = fmin("2026", "mfsp"); z = fmin("2050_NZ", "mfsp")
    d.p(f"«fig:F37_pareto» shows the fronts and «fig:F38_pareto_decisions» the design choices along the 2026 front. The cheapest designs are always HTL plants at the upper area bound of 3,000 ha with biomass heat, wastewater nutrients and a low-carbon PPA (biomass in 2026 and 2040, solar in 2050): {f2(a['mfsp'])} USD/L deq and {f1(a['gwp'])} g/MJ in 2026, and {f2(z['mfsp'])} USD/L deq and {f1(z['gwp'])} g/MJ in 2050. These plants need about 540 kt CO₂ per year, more than the San Carlos plant emits, so their costs assume a second free source of biogenic CO₂. That the optimum sits on the bound means larger plants would be cheaper still, limited in practice by land and by the CO₂ available from one 18 MW power plant. At 25% net efficiency, 8,000 h/yr and the IPCC default of 100 kg CO₂/GJ for solid biomass [@ipcc2006], the plant emits about 207 kt CO₂ per year, enough for roughly 1,150 ha of ponds at the base CO₂ utilisation; larger farms would need a second source. Moving along the front from the cheapest design, the GWP falls further by sending the aqueous phase to CHG and by shrinking the plant so that municipal wastewater covers a larger share of its nitrogen, at a steep cost. FAME appears only at the low-capital end, as very small plants. No design on the 2026 front reaches the CME price; on the 2040 CES2 front the cheapest designs do.")
    d.fig("F38_pareto_decisions"); d.fig("F39_hypervolume")

def surrogate(d):
    d.h1("17. Machine-learning surrogate modelling", bm="sec_ml", pb=True)
    d.p(f"An interactive calculator needs answers in milliseconds in a browser, without the ecoinvent matrices. Surrogates were therefore trained to reproduce four engine outputs (MFSP, GWP, TCI and annual output) from seventeen inputs that a user is likely to change («tab:feat»). For each route {ML['HTL']['n']:,} input vectors were drawn by Latin hypercube sampling over the ranges in «tab:feat», with the three binary design switches drawn as Bernoulli variables, and evaluated on the full engine. Strictly positive outputs with a wide range (MFSP, TCI, output) were modelled in logarithms.")
    rows = [[f[3], f"{f[1]:g}" if f[0] != "log_area" else f"{10**f[1]:.0f} ha", f"{f[2]:g}" if f[0] != "log_area" else f"{10**f[2]:.0f} ha"] for f in ML["feat"]]
    d.table("feat", "Inputs of the surrogates and their training ranges.", ["Input", "Lower", "Upper"], rows, widths=[3.5, 1, 1], align=["l", "r", "r"])
    d.p("Five learners of increasing flexibility were compared using scikit-learn [@pedregosa2011]: a ridge regression on second-order polynomial features; a random forest [@breiman2001]; histogram gradient boosting [@friedman2001]; a multilayer perceptron with two hidden layers of 64 ReLU units, trained with Adam and early stopping; and a Gaussian process with an anisotropic RBF kernel, trained on a 1,500-point subset because its cost grows with the cube of the sample size. Each learner was fitted on 80% of the samples and tested on the remaining 20% («fig:F40_surrogate_models»).")
    d.fig("F40_surrogate_models")
    d.p(f"«fig:F43_permutation» shows what the neural network learned, measured by permutation importance: productivity, liners, the capital multiplier, HTL yield and the discount rate for MFSP; the electricity emission factor, HTL yield, productivity and mixing energy for GWP. For the inputs both analyses share (productivity, yield, discount rate, location factor, mixing energy), the ranking is consistent with the Sobol' indices of the engine, a sign that the surrogate represents the same mechanisms rather than artefacts of the sample; the electricity emission factor ranks higher here because it is trained over a much wider range (0–1.35 kg/kWh).")
    d.fig("F43_permutation")

def surrogate_val(d):
    d.h1("18. Surrogate validation", bm="sec_mlval", pb=True)
    rows = []
    for r in ("HTL", "FAME"):
        for n in MLM[r]:
            m = MLM[r][n]; rows.append([r, n, f"{m['mfsp_ldeq']['r2']:.4f}", pct(m['mfsp_ldeq']['mape'], 1), f"{m['gwp']['r2']:.4f}", pct(m['gwp']['mape'], 1), f"{m['tci']['r2']:.4f}", f"{m['ldeq']['r2']:.4f}", f1(ML[r]['res'][n]['fit_s'])])
    d.table("mlval", "Hold-out performance of the surrogates (20% test set; R² and mean absolute percentage error).", ["Route", "Learner", "MFSP R²", "MAPE", "GWP R²", "MAPE", "TCI R²", "Output R²", "Fit, s"], rows,
            widths=[0.6, 2.1, 0.7, 0.6, 0.7, 0.6, 0.7, 0.7, 0.6], align=["l", "l"] + ["r"] * 7, size=14)
    cvh = ML["HTL"]["cv"]["Neural network (MLP 64-64)"]; cvf = ML["FAME"]["cv"]["Neural network (MLP 64-64)"]
    mh = MLM["HTL"]["Neural network (MLP 64-64)"]; mf = MLM["FAME"]["Neural network (MLP 64-64)"]
    d.p(f"The neural network reproduces the engine with a hold-out R² of {mh['mfsp_ldeq']['r2']:.4f} for MFSP and {mh['gwp']['r2']:.4f} for GWP (HTL), and mean absolute percentage errors of {pct(mh['mfsp_ldeq']['mape'],1)} and {pct(mh['gwp']['mape'],1)} («tab:mlval», «fig:F41_parity»). Five-fold cross-validation gives mean R² of {cvh[:,0].mean():.4f} and {cvh[:,1].mean():.4f} for HTL and {cvf[:,0].mean():.4f} and {cvf[:,1].mean():.4f} for FAME, so the result does not depend on the split; across both routes and both outputs the lowest fold is {min(cvh.min(), cvf.min()):.4f} (FAME GWP). The Gaussian process is even more accurate (R² ≥ 0.9996) but slower to evaluate and harder to deploy; the quadratic ridge model fails for the FAME GWP (R² {MLM['FAME']['Quadratic ridge']['gwp']['r2']:.3f}) and the random forest for MFSP (R² ≈ 0.92–0.93).")
    d.fig("F41_parity")
    lc = ML["HTL"]["lc"]["Neural network (MLP 64-64)"]; ex = ML["HTL"]["extrap"]; exf = ML["FAME"]["extrap"]
    d.p(f"Learning curves («fig:F42_learning_extrap») show that the neural network needs about 4,000 samples to exceed R² = 0.99 and is still improving at 12,800, which justifies the training-set size. To test extrapolation, the surrogates were trained on samples with productivity below 25 g/m²/d and tested above 30. The neural network keeps an R² of {ex['Neural network (MLP 64-64)']['r2']:.2f} for HTL with a MAPE of {pct(ex['Neural network (MLP 64-64)']['mape'],1)}, against 23–29% for the tree and polynomial models; for FAME its MAPE is {pct(exf['Neural network (MLP 64-64)']['mape'],1)}. Extrapolation is therefore possible but unreliable. This experiment used a separate model trained only below 25 g/m²/d; the deployed calculator model is trained over the full 8–40 g/m²/d range, so productivity above 30 g/m²/d is inside its range, and the calculator restricts all inputs to the training ranges.")
    d.fig("F42_learning_extrap")
    d.p(f"These metrics measure agreement with the engine, not accuracy against a real plant. Errors differ by output: for HTL the hold-out MAPE is {pct(mh['mfsp_ldeq']['mape'],1)} for MFSP, {pct(mh['gwp']['mape'],1)} for GWP, {pct(mh['tci']['mape'],1)} for capital and {pct(mh['ldeq']['mape'],1)} for output; for FAME {pct(mf['mfsp_ldeq']['mape'],1)}, {pct(mf['gwp']['mape'],1)}, {pct(mf['tci']['mape'],1)} and {pct(mf['ldeq']['mape'],1)}. Because each network sees all seventeen inputs, it can respond to inputs that have no physical effect on an output; for example, the output network changes slightly when only the hydrogen price changes. This is approximation error. Annual output has a known closed form (Eq. E1, E2, E8 or E10, E13), so the calculator computes it analytically (maximum deviation from the engine {OUTERR:.1e}) instead of from the network. Finally, the exported network weights were evaluated independently in Python and in the browser at the base design: the calculator returns {f2(CALC['HTL']['mfsp_ldeq'])} USD/L deq and {f1(CALC['HTL']['gwp'])} g/MJ for HTL against {f2(H['mfsp_ldeq'])} and {f1(H['gwp'])} from the engine, and {f2(CALC['FAME']['mfsp_ldeq'])} and {f1(CALC['FAME']['gwp'])} for FAME against {f2(F['mfsp_ldeq'])} and {f1(F['gwp'])}. {TIMING_TXT}")

def calculator(d):
    d.h1("19. Prototype web calculator", bm="sec_calc", pb=True)
    d.p("The calculator is a single self-contained web page that embeds the weights of the neural networks for MFSP, GWP and capital of both routes and evaluates them in the browser; annual output is computed analytically from productivity, area and yield («fig:F44_web_calculator»). It needs no server and works offline once loaded. The user chooses the route, starts from one of four example settings and moves seventeen inputs grouped as biology, scale and design, energy, markets and finance. The page shows the MFSP, GWP, capital and output, places the MFSP against the diesel and CME prices and the GWP against the fossil comparator and the RED II thresholds, computes the implied abatement cost, and draws the MFSP across the productivity range with the measured range shaded. Status labels and warnings flag results that depend on extreme inputs. Accuracy figures, method notes and an AI-use statement are shown on the page.")
    d.p([{"t": "The calculator is published at "}, {"link": CALC_URL, "t": CALC_URL}, {"t": " (access is controlled by the owner) and its source is in the project files (calculator.html)."}])
    d.fig("F44_web_calculator", w=470)

def discussion(d):
    d.h1("20. Discussion", bm="sec_disc", pb=True)
    d.h2("20.1 What changes for the original study")
    d.p(f"The 2018 design and the 2021 evaluation were careful in many respects: the unit operations, chemical inventories and fuel quality of the FAME section agree with independent estimates (checks 12, 13 and 23), and the multi-attribute comparison of the three variants is sound as a method [@cereno2018,aviso2021]. The trouble lies upstream. A balance in which almost all of the algae enter as a free input cannot support a cost estimate, because the ponds, the CO₂, the nutrients and the electricity that would produce that biomass are missing from it. Once they are restored, the plant needs about {f0(CORE['area80'])} ha of ponds instead of 10.4, its capital rises roughly twenty-fold, and its cost per litre rises from about {f1(BR[0]['mfsp'])} to about {f1(BR[-1]['mfsp'])} USD diesel-equivalent («fig:F04_bridge»). The ranking of the 2021 variants survives (wastewater nutrients and HTL remain the better choices) but none of them is profitable.")
    d.p("The same applies to our draft 2026 working paper (prepared for the DIW–CentraleSupélec Winter School in December 2026), which re-analysed the 2021 cash flows and found a levelised cost of 0.67–0.74 EUR per litre and a positive NPV in 88% of draws [@cereno2026]. Its corrections to the cash-flow treatment stand, but its conclusion that microalgae could lower the cost of the mandate does not: it inherited the balance. This report supersedes it on that point.")
    d.h2("20.2 Comparison with other studies")
    d.p(f"The PNNL whole-algae HTL design case, 4.49 USD₂₀₁₁ per gallon gasoline-equivalent, corresponds to about 1.9 USD per litre diesel-equivalent in 2025 dollars (CEPCI 813/585.7; 120 MJ per GGE), and the engine reproduces it within {pct(abs(VAL[1]['model']/VAL[1]['published']-1))} when given the PNNL assumptions (Section 5.4) [@jones2014]. The San Carlos design costs {f2(H['mfsp_ldeq'])} USD/L deq, about {f1(H['mfsp_ldeq']/1.9)} times as much, because it processes about one-eighteenth of the biomass of the PNNL design (74 against 1,340 short tons AFDW per day), assumes 20 rather than 25 g/m²/d, grows its own biomass, carries a Southeast Asian location factor and pays Philippine utility prices. The GWP is nearly three times the 33.8 g/MJ of the Argonne assessment of the PNNL pathway because the Visayas grid emits about 2.6 times as much per kWh as the US grid used there [@pegallapati2015]; with a biomass PPA the result ({f1(S['S27']['gwp'])} g/MJ) moves toward the US value.")
    d.h2("20.3 What would make it work")
    d.p(f"The analysis points to a short list. Productivity and HTL yield are the two levers that matter for cost, and both would need to improve by far more than the US programme has achieved in a decade: the CME break-even needs about {f0(be('Productivity for MFSP = CME price (HTL, 2,000 ha)'))} g/m²/d even at 2,000 ha. Low-carbon electricity is the condition for any climate benefit; a PPA with the neighbouring San Carlos BioPower at a GEA-level tariff would be cheap in the model, but whether such a contract would be offered has not been established. Scale helps, but the 18 MW power plant can supply CO₂ to only about 1,150 ha (Section 16). Learning, decarbonisation and biology together bring the HTL MFSP below the fixed CME benchmark in {XOVER[('HTL','NZ')]} (net zero), {XOVER[('HTL','CES2')]} (CES2) and {XOVER[('HTL','CES1')]} (CES1), and not by 2050 on the Reference pathway, but those results depend on assumptions about capacity doublings that a single Philippine plant would not drive.")
    d.h2("20.4 Limitations")
    d.bullets(["The capital estimate is AACE Class 4, scaled from US designs with a regional location factor; no Philippine vendor quotes were obtained.",
               "The HTL and hydrotreating sections are modelled with yields and utilities from PNNL reports, not with a kinetic or rigorous flowsheet model; the HTL aqueous-phase recycle assumes no inhibition of the algae [@zhu2019].",
               f"Six D-rated assumptions enter the HTL base case; the three that matter are the land lease ({f0(B['p_land'])} USD/ha/yr), the rate of damaging typhoons ({B['lam_typh']}/yr) and the days lost per typhoon ({B['typh_days']:g}). None is among the 30 most influential parameters on the combined Morris score, but they should be replaced with site data.",
               "Several inventories are proxies: hydrogen uses a generic ecoinvent hydrogen market while the TEA prices LPG reforming; process heat combines an LPG/natural-gas GWP factor with the other indicators of a natural-gas furnace; the solar scenario covers PV generation only, not battery manufacture, storage losses or backup supply; and the low-voltage grid factor is a conservative proxy for the higher-voltage supply priced in the TEA. The grid factor itself comes from our companion grid model, which is under review and not independently verifiable from this package.",
               "Energy allocation uses one factor for the whole system; it follows the principle of RED II but not its rules for cogeneration and process-step allocation, so the reported savings are indicative and not a compliance calculation.",
               "The engine passes implementation and consistency checks but has no complete element-by-element closure of carbon, nitrogen, ash, upgrading water and off-gases.",
               "Eligibility of HTL renewable diesel, and of algal FAME, under the Biofuels Act is not assessed; CME is used only as an economic benchmark.",
               "The background database is static except for electricity, hydrogen and fertiliser in the prospective scenarios; a fully prospective background, for example with premise [@sacchi2022], would lower future impacts of other inputs as well.",
               "Indirect land-use change is not included; although algae need no arable land in principle, the ponds at this site would occupy sugarcane land, which would shift cane production elsewhere.",
               "Prices are those of September–October 2026, a period of high oil and chemical prices; scenario S37 shows that pre-surge prices change the MFSP little but lower the CME benchmark."])
    d.h2("20.5 Implications for the biodiesel mandate")
    d.p("For the question our working paper asked, whether microalgae fuel could be supplied more cheaply than CME, the answer is no for the coming decade. A litre of algal fuel made at San Carlos in 2026 would cost about twice as much as CME and, on the current grid, give a negligible GHG saving. Whether HTL renewable diesel could count toward the mandate at all would require a separate regulatory determination under the Biofuels Act, which defines biodiesel as an ester from vegetable oil or animal fats approved by the Department of Energy [@ra9367]. In that period, diversifying biodiesel feedstock away from coconut would have to rely on other feedstocks. Algae become relevant only from the late 2030s at the earliest and only together with a clean grid, and a pilot programme that measures productivity at the site over several years would be the right next step if that option is to be kept open.")

def conclusions(d):
    d.h1("21. Conclusions and recommendations", bm="sec_concl", pb=True)
    d.bullets([f"RQ1. The inherited balance does not hold: {NVFAIL} of {NVER} checks of the balance and workbooks do not hold, each traced to a sheet and cell or a thesis page. The algae are fed rather than grown, the implied productivity is 772–2,008 g/m²/d, the HTL reactor has no heat duty, and nutrients and CO₂ cover less than 1% of demand.",
            f"RQ2. For a corrected 400 ha plant in 2026, HTL costs {f2(H['mfsp_ldeq'])} USD/L deq and emits {f1(H['gwp'])} g CO₂e/MJ; FAME costs {f2(F['mfsp_ldeq'])} and emits {f1(F['gwp'])}. Both are above the CME benchmark ({f2(CME)}); on the Visayas grid the HTL route gives a negligible deterministic GHG saving ({H['saving']*100:.1f}%) and FAME {pct(F['saving'])}. CME is an economic benchmark; mandate eligibility of HTL fuel is not assumed.",
            f"RQ3. Electricity supply decides the climate result (a hypothetical biomass PPA gives {f1(S['S27']['gwp'])} g/MJ); productivity, yield and scale decide the cost. The CME break-even needs {f0(be('Productivity for MFSP = CME price (HTL)'))} g/m²/d at 400 ha. The HTL MFSP falls below the fixed CME benchmark in {XOVER[('HTL','NZ')]} on the net-zero pathway, {XOVER[('HTL','CES2')]} on CES2 and {XOVER[('HTL','CES1')]} on CES1, not by 2050 on the Reference pathway, and reaches {f2(S['S54']['mfsp_ldeq'])} USD/L deq by 2050 on the net-zero pathway.",
            f"RQ4. Under uncertainty none of the evaluated 2026 designs reaches the CME benchmark in more than 1 of 10,000 draws; with independent inputs, the first-order Sobol' indices of productivity and HTL yield sum to {pct(s1sum('HTL')[0])} of the variance of the MFSP. In 2050 on the net-zero pathway the model probability of an MFSP below CME is {pct(pr('S54 HTL NZ 2050','p_lt_cme'))} against the fixed benchmark and {pct(pr('S54 HTL NZ 2050','p_lt_cme_sampled'))} against the sampled price, conditional on that pathway.",
            f"RQ5. Within an optimisation that does not constrain CO₂ supply, Pareto-optimal low-cost designs are large HTL plants with a low-carbon PPA, biomass heat and wastewater nutrients ({f2(fmin('2026','mfsp')['mfsp'])} USD/L deq and {f1(fmin('2026','mfsp')['gwp'])} g/MJ in 2026).",
            f"RQ6. A two-layer neural network reproduces the engine with hold-out R² of {MLR2[0]:.3f}–{MLR2[1]:.3f}; for HTL its mean absolute percentage errors are {pct(MLM['HTL']['Neural network (MLP 64-64)']['mfsp_ldeq']['mape'],1)} for MFSP, {pct(MLM['HTL']['Neural network (MLP 64-64)']['gwp']['mape'],1)} for GWP and {pct(MLM['HTL']['Neural network (MLP 64-64)']['tci']['mape'],1)} for capital. These measure agreement with the engine, not with a real plant. The networks drive the published calculator, which computes output analytically."])
    d.p("We recommend: (i) not to pursue a commercial microalgae fuel plant at San Carlos on present technology; (ii) if the option is to be kept open, to run a multi-year outdoor pilot at the site to measure productivity, culture stability and the effect of recycled HTL aqueous phase; (iii) to treat low-carbon electricity as a condition of any future project, and to confirm with San Carlos BioPower whether a supply contract at a GEA-level tariff could be offered; (iv) to replace the D-rated assumptions, above all the land lease and the typhoon frequency and outage length, with site data; (v) to ask the Department of Energy whether HTL renewable diesel or algal FAME could count toward the biodiesel mandate before any further investment; and (vi) to treat microalgae as an option for the late 2030s to 2040s in fuel planning, alongside feedstocks closer to the CME cost.")

def documentation(d):
    d.h1("22. Research documentation and reporting", bm="sec_doc", pb=True)
    d.p("The study is documented so that every number can be traced and reproduced («tab:manifest»). The project database is a results database: it holds exported values, not live spreadsheet formulas, and the calculations are reproduced by running the model code package. All inputs live in the registry; the engine and the analysis scripts read only from it; and every figure is generated by a script that also writes the data behind it to the figure registry, from which the project database is built. The database repeats the figures as images, each on its own sheet with its data.")
    rows = [["Integrated report (this document)", "Word (.docx)", "All sections, figures, tables, references and appendices"], ["Manuscript", "Word (.docx)", "Journal-style article based on this report"],
            ["Presentation", "Slides artifact (exportable to .pptx/PDF)", "Detailed deck with speaker notes and appendices"], ["Project database", "Excel (.xlsx)", "Registry, references, original data, verification, balances, LCI/LCIA, TEA, scenarios, sensitivity, uncertainty, risk, GSA, Pareto, surrogate, figures with data"],
            ["Web calculator", "HTML page (published artifact)", "Neural-network surrogate in the browser"], ["Model code package", "ZIP of Python modules with README and requirements", "registry, model (engine), scen, verify, validate, closure, run_core, run_unc, run_opt, run_ml, figure scripts, document builders, random seeds; the ecoinvent matrices are licensed and excluded, with activity and method identifiers listed in the database"]]
    d.table("manifest", "Deliverables of the study.", ["Deliverable", "Format", "Content"], rows, widths=[1.8, 1.8, 3.4])
    d.p(f"Quality assurance comprised the verification and validation of Section 5; an automated check of all {len(REFS)} references against Crossref and publisher records, which corrected 39 entries and replaced one source that did not support its citation (a figure label citing a study that could not be located was also replaced with a verified source); independent re-evaluation of the surrogate in two languages; and a review of every figure for legibility. Text, tables and figure captions in this report draw their numbers directly from the model outputs through the document builder, so that no value is transcribed by hand. Model runs used Python 3.13 with NumPy, SciPy and scikit-learn; ecoinvent 3.12 was used under licence and is not redistributed, but the unit scores used are listed per flow in the database.")

def appendices(d):
    d.h1("Appendix A. Scenario definitions", bm="app_a", pb=True)
    rows = []
    for sid in sorted(SDEF):
        s = SDEF[sid]; base = dict(route="HTL", area_ha=400.0, lined=False, co2="flue", nutr="fert", aq="recycle", upgrade="onsite", heat="fossil", elec="grid", alloc="energy")
        if s["D"].get("route") == "FAME": base = {**base, "route": "FAME", "glyc": "crude"}
        dd = {k: v for k, v in s["D"].items() if base.get(k) != v and k != "route"}
        txt = "; ".join(f"{k} = {v}" for k, v in dd.items())
        if s["P"]: txt += ("; " if txt else "") + "; ".join(f"{k} = {v:g}" for k, v in s["P"].items())
        if s.get("pros"): txt += ("; " if txt else "") + f"prospective {s['pros']}"
        rows.append([sid, s["D"].get("route"), s["name"], txt or "base"])
    d.table("appA", "Definitions of the 60 scenarios: changes from the base design of each route.", ["ID", "Route", "Scenario", "Changes from base"], rows, widths=[0.45, 0.6, 2.8, 3.2], size=13)
    d.h1("Appendix B. Parameter registry", bm="app_b", pb=True)
    rows = [[r["key"], r["name"], f"{r['base']:g}", f"{r['low']:g}–{r['high']:g}", r["unit"], r["dist"], r["conf"], [{"citek": r["src"]}] if r["src"] else ["derived"]] for r in REG.R]
    d.b.append({"k": "table", "tid": "appB", "bm": "tab_appB", "cap": ["Complete parameter registry."], "head": [[h] for h in ["Key", "Parameter", "Base", "Range", "Unit", "Dist.", "Conf.", "Sources"]],
                "rows": [[(c if isinstance(c, list) else [str(c)]) for c in r] for r in rows], "widths": [0.9, 2.2, 0.7, 1.0, 1.0, 0.4, 0.4, 1.1], "align": ["l", "l", "r", "r", "l", "l", "l", "l"], "note": None, "size": 12})
    d.h1("Appendix C. Stream table of Route B", bm="app_c", pb=True)
    sf = FIG["F01c_pfd_fame"]["data"]
    d.table("streams_fame", "Stream table of Route B at the 2026 base design (annual flows; numbers as in the FAME process flow diagram).", ["Stream", "Description", "Flow", "Unit", "Note"],
            [[r["stream"], r["description"], (f"{r['value']:,.3g}" if abs(r['value']) < 100 else f"{r['value']:,.0f}"), r["unit"], r.get("note", "")] for r in sf], widths=[0.6, 2.6, 1.0, 1.1, 2.6], align=["l", "l", "r", "l", "l"], size=15)
    d.h1("Appendix D. Findings of the original studies", bm="app_d", pb=True)
    d.p("This appendix records the principal results of the three earlier studies on the San Carlos plant, as reported, with peso values converted at the 2026 rate of PHP 60.75 per USD without inflation adjustment. They are reproduced to credit the original work and to make the comparison in Section 5 traceable.")
    rows = [["Algal biomass to conversion", "80 t/d (79.5 t/d fed as culture, 0.5 t/d grown)", [{"citek": ["cereno2018"]}]], ["Ponds", "96 open raceways of 1,079 m² (10.36 ha); 3.98 ha in the plant layout", [{"citek": ["cereno2018"]}]],
            ["Biodiesel output", "8,711.5 t/yr (10.0 ML/yr at 870 kg/m³)", [{"citek": ["cereno2018"]}]], ["FAME from transesterification", "29.07 t/d", [{"citek": ["cereno2018"]}]],
            ["Total project cost", "PHP 469–1,048 M (USD 7.7–17.3 M), three versions", [{"citek": ["cereno2018"]}]], ["Glycerol purity", "57.8–92.6% (by section)", [{"citek": ["cereno2018", "aviso2021"]}]],
            ["Alternative 1 (HTL)", "NPV PHP −2,025 M (USD −33.3 M); ROI −19.8%; 207 jobs", [{"citek": ["aviso2021"]}]], ["Alternative 2 (+ wastewater)", "NPV PHP 668 M (USD 11.0 M); ROI 11.0%; payback 9.4 yr; 209 jobs", [{"citek": ["aviso2021"]}]],
            ["Alternative 3 (+ glycerol purification)", "NPV PHP 1,042 M (USD 17.1 M); ROI 15.2%; payback 6.3 yr; 219 jobs; ranked first", [{"citek": ["aviso2021"]}]], ["Biodiesel sales, Alt. 2 and 3", "PHP 614.8 M/yr (USD 10.1 M/yr)", [{"citek": ["aviso2021"]}]],
            ["Glycerol sales, Alt. 3", "PHP 51.9 M/yr (USD 0.85 M/yr)", [{"citek": ["aviso2021"]}]], ["Levelised cost, Alt. 3 (unlevered, 8%)", "EUR 0.67–0.74/L (PHP 47.7–52.7; USD 0.79–0.87/L)", [{"citek": ["cereno2026"]}]],
            ["Unlevered NPV, Alt. 3 (8%)", "EUR 7.3–14.0 M (USD 8.6–16.4 M); IRR 19–52%", [{"citek": ["cereno2026"]}]], ["Value of the income-tax holiday", "EUR 3.4 M (USD 4.0 M)", [{"citek": ["cereno2026"]}]],
            ["Monte Carlo (20,000 draws)", "NPV positive in 88% of draws", [{"citek": ["cereno2026"]}]]]
    d.b.append({"k": "table", "tid": "appD", "bm": "tab_appD", "cap": ["Principal findings of the original studies."], "head": [[h] for h in ["Quantity", "Reported value", "Source"]],
                "rows": [[(c if isinstance(c, list) else [str(c)]) for c in r] for r in rows], "widths": [2.2, 3.8, 0.9], "align": None, "note": None, "size": 15})

