def app_revision(d):
    d.h1("Appendix F. Revision log (version 1.1)", bm="app_f", pb=True)
    d.p("Version 1.1 responds to the internal review by S. G. Cereno and to a seven-file accuracy review (both 17 October 2026). The model was corrected and every analysis was rerun; the table lists each point and what changed.")
    rows = [
        ["Conversion capital factor counted working capital twice", "FCI/installed set to (467.9 − 22.3)/252.6 = 1.764 (PNNL); farm 1.64/1.05 = 1.562 (NREL TCI includes 5% WC); WC added once", f"HTL MFSP 4.86 → {H['mfsp_ldeq']:.2f} USD/L deq; FAME 14.65 → {F['mfsp_ldeq']:.2f}"],
        ["Bridge did not hold conversion feed constant", f"Bridge now holds 24,000 t/yr entering conversion: {CORE['area80']:.0f} ha (was 371 ha)", "Fig. 4, Table 8 and abstract updated"],
        ["HTL nitrogen recycle on biomass grown", f"Computed on harvested biomass entering HTL ({H['N_rec']:.0f} t N/yr, was 707); digestate N likewise", "Small rise in urea purchase and GWP"],
        ["FAME extract not accounted in digestion", f"Non-transesterifiable extract ({F['extract_ret']:.0f} t/yr) shown as stream 19 returned to AD; consistency check added", "Balance unchanged, now explicit"],
        ["Stream bases inconsistent (cake vs HTL slurry)", "Dilution water stream 8a added; AFDW, total dry solids and wet bases labelled", "Stream table reconciled"],
        ["Tax losses carried indefinitely", "Loss vintages: ITH-period losses not carried (NIRC 34(D)(3)); later losses expire after 5 years (enhanced NOLCO); same rule in stochastic model", "NPV at CME slightly lower"],
        ["Mandate eligibility assumed", "CME treated as economic benchmark only; RA 9367 definition stated; title and conclusions revised", "Text only"],
        ["Equations lacked unit conversions", "0.01 and 10 factors and units added (E1, E5, E6, E7, E11)", "Text only"],
        ["Closure checks overstated", f"Renamed implementation and consistency checks ({NCHK}); limits of elemental closure stated", "Text only"],
        ["Benchmark definition for P(MFSP<CME)", "Fixed and sampled benchmarks reported separately", "New risk column"],
        ["Sobol' dependency convention and 65% sum", "Independent-input convention stated; first-order sum reported", "Text only"],
        ["Surrogate accuracy and invariance", "MAPE by output; output computed analytically; irrelevant inputs held at base; browser timing measured", "Calculator rebuilt"],
        ["EF 3.0 vs EF 3.1 reference; LCIA units missing", "Reference changed to Fazio et al. (EF 3.0); units for all 183 indicators", "Database 09_LCIA"],
        ["Proxies (voltage, H₂, heat, PV/BESS), RED II wording, comparator boundary, PPA availability", "Disclosed in registry, methods, limitations; RED II 50/60/65% thresholds", "Text only"],
        ["Labels: 2,000 ha (2,023 modelled), 500 ha land, mixed USD 2025/2026, crossover dates", f"Relabelled; crossovers {XOVER[('HTL','NZ')]} (NZ), {XOVER[('HTL','CES2')]} (CES2), {XOVER[('HTL','CES1')]} (CES1), none (REF)", "Text only"],
        ["Original workbooks: #REF! errors; verification sources", "Check 24 added; every check carries its sheet/cell or page", f"{NVFAIL} of {NVER} checks fail"],
        ["Reproducibility", "Model code package (zip) with requirements and seeds; database described as results database", "New deliverable"],
    ]
    d.table("revlog", "Revision log: review points, changes and effect on results.", ["Review point", "Change", "Effect"], rows, widths=[2.2, 3.2, 1.6], size=13)
